window.QBANK = window.QBANK || {};
window.QBANK["sd-pjok"] = {
  level: "SD", subject: "PJOK", duration: 900,
  questions: [
    { q: "Gerak berpindah tempat dari satu tempat ke tempat lain disebut gerak ...", options: ["nonlokomotor", "manipulatif", "lokomotor", "statis"], answer: 2, solution: "1. Gerak dasar dibagi menjadi tiga: lokomotor, nonlokomotor, dan manipulatif. 2. Gerak yang membuat tubuh berpindah tempat disebut gerak lokomotor. 3. Contohnya berjalan, berlari, dan melompat." },
    { q: "Contoh gerak lokomotor adalah ...", options: ["berlari", "membungkuk", "memutar badan", "mengayun lengan"], answer: 0, solution: "1. Gerak lokomotor adalah gerak berpindah tempat. 2. Berlari membuat tubuh berpindah dari satu tempat ke tempat lain. 3. Membungkuk, memutar badan, dan mengayun lengan tidak membuat tubuh berpindah tempat." },
    { q: "Melompat adalah gerakan menolak dengan ...", options: ["dua kaki", "satu kaki", "tangan", "kepala"], answer: 1, solution: "1. Melompat dan meloncat terlihat mirip, tetapi berbeda. 2. Melompat menolak dengan satu kaki, contohnya lompat jangkit. 3. Meloncat menolak dengan dua kaki, contohnya lompat tali." },
    { q: "Meloncat adalah gerakan menolak dengan ...", options: ["dua kaki", "satu kaki", "lutut", "siku"], answer: 0, solution: "1. Meloncat adalah gerak menolak ke atas atau ke depan. 2. Tolakannya memakai dua kaki sekaligus. 3. Contohnya meloncat saat bermain lompat tali." },
    { q: "Berjalan, berlari, dan melompat termasuk gerak ...", options: ["nonlokomotor", "manipulatif", "kombinasi", "lokomotor"], answer: 3, solution: "1. Berjalan, berlari, dan melompat sama-sama membuat tubuh berpindah tempat. 2. Gerak berpindah tempat disebut gerak lokomotor. 3. Jadi ketiganya termasuk gerak lokomotor." },
    { q: "Melangkah ke depan, ke belakang, dan ke samping termasuk gerak ...", options: ["nonlokomotor", "lokomotor", "manipulatif", "diam"], answer: 1, solution: "1. Melangkah membuat kaki bergerak dan tubuh berpindah tempat. 2. Gerak yang membuat tubuh berpindah tempat disebut gerak lokomotor. 3. Jadi melangkah termasuk gerak lokomotor." },
    { q: "Bermain lompat tali (skipping) termasuk gerak ...", options: ["nonlokomotor", "pasif", "lokomotor", "manipulatif"], answer: 2, solution: "1. Saat lompat tali, tubuh meloncat dan berpindah naik-turun. 2. Gerak berpindah tempat termasuk gerak lokomotor. 3. Jadi lompat tali termasuk gerak lokomotor." },
    { q: "Gerak yang dilakukan tanpa berpindah tempat disebut gerak ...", options: ["nonlokomotor", "lokomotor", "manipulatif", "berpindah"], answer: 0, solution: "1. Gerak nonlokomotor artinya gerak di tempat. 2. Tubuh bergerak tetapi tidak berpindah dari tempatnya. 3. Contohnya membungkuk, jongkok, dan memutar badan." },
    { q: "Contoh gerak nonlokomotor adalah ...", options: ["berlari", "melompat", "berjalan", "membungkuk"], answer: 3, solution: "1. Gerak nonlokomotor dilakukan tanpa berpindah tempat. 2. Membungkuk hanya menggerakkan badan di tempat. 3. Berlari, melompat, dan berjalan membuat tubuh berpindah tempat." },
    { q: "Mengayunkan lengan dan memutar pinggang termasuk gerak ...", options: ["lokomotor", "nonlokomotor", "manipulatif", "melompat"], answer: 1, solution: "1. Mengayunkan lengan dan memutar pinggang dilakukan di tempat. 2. Tubuh tidak berpindah ke tempat lain. 3. Jadi keduanya termasuk gerak nonlokomotor." },
    { q: "Gerakan jongkok di tempat tanpa berpindah termasuk gerak ...", options: ["lokomotor", "manipulatif", "nonlokomotor", "lari"], answer: 2, solution: "1. Jongkok di tempat hanya menekuk lutut dan badan. 2. Tubuh tetap di tempatnya, tidak berpindah. 3. Jadi jongkok termasuk gerak nonlokomotor." },
    { q: "Meliukkan badan ke kanan dan ke kiri termasuk gerak ...", options: ["nonlokomotor", "lokomotor", "manipulatif", "berguling"], answer: 0, solution: "1. Meliukkan badan dilakukan sambil berdiri di tempat. 2. Tubuh tidak berpindah tempat. 3. Jadi meliukkan badan termasuk gerak nonlokomotor." },
    { q: "Gerak yang dilakukan dengan menggunakan alat atau benda disebut gerak ...", options: ["lokomotor", "manipulatif", "nonlokomotor", "bebas"], answer: 1, solution: "1. Gerak manipulatif adalah gerak yang melibatkan benda atau alat. 2. Contohnya melempar bola, menangkap bola, dan menendang bola. 3. Jadi gerak dengan alat disebut gerak manipulatif." },
    { q: "Contoh gerak manipulatif adalah ...", options: ["membungkuk", "berlari", "melempar bola", "jongkok"], answer: 2, solution: "1. Gerak manipulatif selalu memakai benda atau alat. 2. Melempar bola memakai bola sebagai bendanya. 3. Membungkuk, berlari, dan jongkok tidak memakai benda." },
    { q: "Menangkap bola termasuk gerak ...", options: ["manipulatif", "lokomotor", "nonlokomotor", "diam"], answer: 0, solution: "1. Menangkap bola melibatkan benda, yaitu bola. 2. Gerak yang memakai benda disebut gerak manipulatif. 3. Jadi menangkap bola termasuk gerak manipulatif." },
    { q: "Menendang bola termasuk gerak ...", options: ["nonlokomotor", "lokomotor", "melayang", "manipulatif"], answer: 3, solution: "1. Menendang bola memakai kaki untuk menggerakkan bola. 2. Karena ada bendanya (bola), gerak ini disebut gerak manipulatif. 3. Jadi menendang bola termasuk gerak manipulatif." },
    { q: "Memantulkan bola basket ke lantai (dribbling) termasuk gerak ...", options: ["lokomotor", "manipulatif", "nonlokomotor", "melompat"], answer: 1, solution: "1. Dribbling adalah memantulkan bola ke lantai berulang-ulang. 2. Gerakan ini memakai benda yaitu bola basket. 3. Jadi dribbling termasuk gerak manipulatif." },
    { q: "Memukul bola kasti dengan pemukul termasuk gerak ...", options: ["manipulatif", "nonlokomotor", "lokomotor", "berguling"], answer: 0, solution: "1. Memukul bola kasti memakai alat pemukul dan bola. 2. Gerak yang memakai alat atau benda disebut gerak manipulatif. 3. Jadi memukul bola kasti termasuk gerak manipulatif." },
    { q: "Jumlah pemain sepak bola dalam satu tim adalah ... orang.", options: ["9", "7", "11", "5"], answer: 2, solution: "1. Sepak bola dimainkan oleh dua tim yang berlawanan. 2. Setiap tim terdiri dari 11 pemain, termasuk penjaga gawang. 3. Jadi jumlah pemain sepak bola satu tim adalah 11 orang." },
    { q: "Lama permainan sepak bola adalah ...", options: ["2 x 40 menit", "2 x 45 menit", "2 x 30 menit", "1 x 90 menit"], answer: 1, solution: "1. Permainan sepak bola dibagi menjadi dua babak. 2. Setiap babak lamanya 45 menit, jadi total 2 x 45 menit. 3. Di antara dua babak ada waktu istirahat." },
    { q: "Dalam sepak bola, pemain tidak boleh menyentuh bola dengan tangan, kecuali ...", options: ["penjaga gawang (kiper)", "penyerang", "gelandang", "bek"], answer: 0, solution: "1. Aturan sepak bola melarang pemain memegang bola dengan tangan. 2. Hanya penjaga gawang (kiper) yang boleh menangkap bola dengan tangan. 3. Itu pun hanya di dalam kotak penalti." },
    { q: "Jumlah pemain bola voli dalam satu tim adalah ... orang.", options: ["5", "11", "9", "6"], answer: 3, solution: "1. Bola voli dimainkan oleh dua tim yang dipisahkan net. 2. Setiap tim terdiri dari 6 pemain. 3. Jadi jumlah pemain bola voli satu tim adalah 6 orang." },
    { q: "Dalam bola voli, satu tim boleh menyentuh bola maksimal ... kali sebelum menyeberangkan net.", options: ["2", "4", "3", "5"], answer: 2, solution: "1. Aturan bola voli membatasi sentuhan bola. 2. Satu tim boleh menyentuh bola maksimal 3 kali. 3. Sentuhan keempat dianggap pelanggaran." },
    { q: "Pukulan untuk memulai permainan bola voli disebut ...", options: ["smash", "servis", "passing", "blocking"], answer: 1, solution: "1. Setiap reli dalam bola voli diawali dengan satu pukulan. 2. Pukulan pembuka itu disebut servis. 3. Servis dilakukan dari belakang garis lapangan." },
    { q: "Jumlah pemain bola basket dalam satu tim yang bermain di lapangan adalah ... orang.", options: ["5", "6", "7", "11"], answer: 0, solution: "1. Bola basket dimainkan dua tim yang berebut memasukkan bola ke ring. 2. Setiap tim menurunkan 5 pemain di lapangan. 3. Jadi jumlah pemain bola basket satu tim adalah 5 orang." },
    { q: "Tembakan bernilai 3 poin dalam bola basket dilakukan dari ...", options: ["dalam garis tiga angka", "tengah lapangan", "bawah ring", "luar garis tiga angka"], answer: 3, solution: "1. Dalam bola basket ada tembakan 1 poin, 2 poin, dan 3 poin. 2. Tembakan 3 poin harus dilakukan dari luar garis tiga angka. 3. Tembakan dari dalam garis hanya bernilai 2 poin." },
    { q: "Gerakan memantulkan bola sambil berjalan atau berlari dalam bola basket disebut ...", options: ["shooting", "dribbling", "passing", "pivot"], answer: 1, solution: "1. Pemain basket tidak boleh membawa bola sambil berlari. 2. Bola harus dipantulkan ke lantai, gerakan ini disebut dribbling. 3. Shooting artinya menembak, passing artinya mengoper." },
    { q: "Permainan kasti dimainkan oleh ... regu yang saling berlawanan.", options: ["2", "3", "4", "1"], answer: 0, solution: "1. Kasti adalah permainan bola kecil beregu. 2. Permainan ini dimainkan oleh 2 regu: regu pemukul dan regu penjaga. 3. Kedua regu bergantian memukul dan menjaga." },
    { q: "Alat yang digunakan untuk memukul bola dalam permainan kasti adalah ...", options: ["raket", "tangan kosong", "pemukul kayu", "kaki"], answer: 2, solution: "1. Dalam permainan kasti, bola kecil dipukul agar melambung jauh. 2. Alat pemukulnya terbuat dari kayu. 3. Jadi alatnya disebut pemukul kayu." },
    { q: "Dalam permainan kasti, bola dilambungkan oleh ...", options: ["pemukul", "pelambung", "penjaga", "wasit"], answer: 1, solution: "1. Sebelum dipukul, bola harus dilambungkan terlebih dahulu. 2. Orang yang bertugas melambungkan bola disebut pelambung. 3. Setelah bola dilambung, pemukul memukulnya sejauh mungkin." },
    { q: "Setelah berhasil memukul bola, pemain kasti harus berlari menuju ...", options: ["gawang", "garis finis", "wasit", "tiang hinggap"], answer: 3, solution: "1. Setelah memukul bola, pemain berlari untuk mengumpulkan poin. 2. Pemain berlari menuju tiang-tiang hinggap yang tersedia. 3. Semakin banyak tiang hinggap yang dilewati, semakin banyak poinnya." },
    { q: "Permainan rounders hampir sama dengan permainan ...", options: ["kasti", "sepak bola", "bola voli", "basket"], answer: 0, solution: "1. Rounders adalah permainan bola kecil beregu. 2. Cara mainnya mirip kasti: memukul bola lalu berlari ke base. 3. Jadi rounders hampir sama dengan permainan kasti." },
    { q: "Jumlah pemain rounders dalam satu tim adalah ... orang.", options: ["11", "6", "9", "5"], answer: 2, solution: "1. Rounders dimainkan oleh dua tim. 2. Setiap tim terdiri dari 9 pemain. 3. Jadi jumlah pemain rounders satu tim adalah 9 orang." },
    { q: "Latihan push-up berguna untuk melatih kekuatan otot ...", options: ["perut", "lengan", "kaki", "leher"], answer: 1, solution: "1. Push-up dilakukan dengan mendorong tubuh naik-turun bertumpu pada tangan. 2. Gerakan ini melatih kekuatan otot lengan dan dada. 3. Jadi push-up berguna untuk otot lengan." },
    { q: "Latihan sit-up berguna untuk melatih kekuatan otot ...", options: ["perut", "lengan", "punggung", "betis"], answer: 0, solution: "1. Sit-up dilakukan dengan mengangkat badan dari posisi tidur. 2. Gerakan ini melatih kekuatan otot perut. 3. Otot perut yang kuat membuat tubuh tidak mudah bungkuk." },
    { q: "Lari jarak jauh secara rutin berguna untuk melatih ...", options: ["kekuatan jari", "kelenturan leher", "kecepatan berpikir", "daya tahan jantung dan paru-paru"], answer: 3, solution: "1. Lari jarak jauh membuat jantung dan paru-paru bekerja keras. 2. Kalau rutin, jantung dan paru-paru menjadi kuat dan tidak mudah lelah. 3. Jadi lari melatih daya tahan jantung dan paru-paru." },
    { q: "Latihan kelenturan tubuh dapat dilakukan dengan gerakan ...", options: ["push-up", "sit-up", "mencium lutut", "lari cepat"], answer: 2, solution: "1. Kelenturan artinya tubuh mudah ditekuk dan tidak kaku. 2. Gerakan mencium lutut melatih kelenturan otot kaki dan punggung. 3. Push-up dan sit-up melatih kekuatan, bukan kelenturan." },
    { q: "Agar tubuh tetap bugar, olahraga sebaiknya dilakukan secara ...", options: ["sekali setahun", "teratur", "hanya saat sakit", "sambil begadang"], answer: 1, solution: "1. Olahraga yang jarang tidak membuat tubuh bugar. 2. Olahraga harus dilakukan secara teratur, misalnya 3 kali seminggu. 3. Olahraga teratur membuat tubuh sehat dan kuat." },
    { q: "Squat jump adalah latihan untuk kekuatan otot ...", options: ["kaki", "lengan", "perut", "dada"], answer: 0, solution: "1. Squat jump dilakukan dengan jongkok lalu meloncat setinggi mungkin. 2. Gerakan meloncat bertumpu pada kekuatan kaki. 3. Jadi squat jump melatih kekuatan otot kaki." },
    { q: "Makanan yang baik untuk tubuh adalah makanan yang ...", options: ["banyak gula", "banyak pewarna", "cepat saji setiap hari", "bergizi seimbang"], answer: 3, solution: "1. Tubuh butuh karbohidrat, protein, vitamin, dan mineral. 2. Makanan bergizi seimbang mengandung semua itu dalam jumlah pas. 3. Terlalu banyak gula dan pewarna justru merusak tubuh." },
    { q: "Agar tubuh tetap segar saat beraktivitas, kita perlu tidur dan istirahat yang ...", options: ["sedikit", "begadang", "cukup", "tidak teratur"], answer: 2, solution: "1. Tidur berguna memulihkan tenaga tubuh. 2. Anak SD butuh tidur yang cukup setiap malam. 3. Kurang tidur membuat tubuh lemas dan sulit konsentrasi." },
    { q: "Mencuci tangan sebelum makan berguna untuk ...", options: ["membuang waktu", "mencegah kuman masuk ke tubuh", "menghabiskan sabun", "mendinginkan tangan"], answer: 1, solution: "1. Tangan yang kotor penuh kuman penyakit. 2. Kalau langsung makan, kuman ikut masuk ke mulut. 3. Mencuci tangan dengan sabun mencegah kuman masuk ke tubuh." },
    { q: "Minuman yang paling baik untuk tubuh adalah ...", options: ["air putih", "minuman bersoda", "minuman beralkohol", "sirup kental"], answer: 0, solution: "1. Tubuh manusia sebagian besar terdiri dari air. 2. Air putih mengganti cairan tubuh tanpa tambahan gula. 3. Minuman bersoda dan sirup terlalu banyak gula." },
    { q: "Gosok gigi sebaiknya dilakukan ... kali dalam sehari.", options: ["1", "5", "2", "7"], answer: 2, solution: "1. Sisa makanan yang menempel di gigi bisa membuat gigi berlubang. 2. Gosok gigi 2 kali sehari: pagi setelah sarapan dan malam sebelum tidur. 3. Gigi yang bersih membuat napas segar." },
    { q: "Sarapan pagi itu penting karena memberi ...", options: ["rasa kantuk", "energi untuk beraktivitas", "penyakit", "kegemukan"], answer: 1, solution: "1. Setelah tidur semalaman, perut kosong dan tubuh butuh tenaga. 2. Sarapan memberi energi untuk belajar dan bermain. 3. Anak yang sarapan lebih fokus di sekolah." },
    { q: "Sebelum berolahraga, sebaiknya kita melakukan ...", options: ["pemanasan", "pendinginan", "tidur", "makan banyak"], answer: 0, solution: "1. Otot yang dingin dan kaku mudah cedera kalau langsung dipakai berat. 2. Pemanasan membuat otot hangat dan lentur. 3. Jadi sebelum olahraga wajib pemanasan dulu." },
    { q: "Tujuan melakukan pemanasan sebelum berolahraga adalah ...", options: ["membuat cepat lelah", "menambah berat badan", "mengurangi semangat", "mencegah cedera otot"], answer: 3, solution: "1. Pemanasan menaikkan suhu tubuh dan melenturkan otot. 2. Otot yang lentur tidak mudah terkilir atau kram. 3. Jadi tujuan pemanasan adalah mencegah cedera otot." },
    { q: "Setelah selesai berolahraga, sebaiknya kita melakukan ...", options: ["langsung duduk lama", "langsung makan banyak", "pendinginan", "langsung tidur"], answer: 2, solution: "1. Setelah olahraga, jantung masih berdetak cepat. 2. Pendinginan menenangkan jantung dan otot secara perlahan. 3. Jadi setelah olahraga sebaiknya pendinginan dulu." },
    { q: "Saat bersepeda, alat pelindung kepala yang wajib dipakai adalah ...", options: ["topi pantai", "helm", "kacamata hitam", "masker"], answer: 1, solution: "1. Kepala harus dilindungi saat bersepeda. 2. Helm melindungi kepala kalau terjatuh. 3. Topi pantai dan kacamata tidak melindungi kepala." },
    { q: "Sepatu yang baik dipakai untuk berolahraga adalah sepatu ...", options: ["olahraga yang pas di kaki", "hak tinggi", "sendal jepit", "sepatu sempit"], answer: 0, solution: "1. Kaki butuh penyangga yang nyaman saat olahraga. 2. Sepatu olahraga yang pas melindungi kaki dari lecet dan terkilir. 3. Sepatu hak tinggi dan sendal jepit berbahaya untuk olahraga." },
{ q: "Gerakan gallop meniru cara bergerak hewan apa?", options: ["Kucing", "Katak", "Ikan", "Kuda"], answer: 3, solution: "1. Gallop adalah gerak melangkah melompat ke samping seperti kuda berlari kecil. 2. Satu kaki selalu memimpin di depan lalu kaki lain menyusul. 3. Karena itu gallop meniru gerakan kuda." },
{ q: "Langkah geser (slide) ke samping dilakukan dengan cara...", options: ["Merangkak ke samping", "Melompat tinggi dengan dua kaki", "Berlari cepat ke depan", "Satu kaki melangkah ke samping lalu kaki lain menyusul"], answer: 3, solution: "1. Slide diawali satu kaki melangkah ke samping. 2. Kaki yang lain segera menyusul tanpa menyilang. 3. Gerakan ini membuat tubuh berpindah tempat ke samping." },
{ q: "Skipping adalah gerakan...", options: ["Berdiri dengan satu kaki", "Tidur di lantai", "Duduk diam di tempat", "Melompat-lompat kecil sambil bergerak maju"], answer: 3, solution: "1. Skipping dilakukan dengan lompatan-lompatan kecil. 2. Tubuh tetap bergerak maju saat melakukannya. 3. Gerakan ini sering dipakai untuk pemanasan sebelum berlari." },
{ q: "Gerakan hopping dilakukan dengan tumpuan...", options: ["Satu kaki yang sama berulang-ulang", "Dua kaki bergantian", "Tangan dan kaki", "Kepala"], answer: 0, solution: "1. Hopping artinya melompat dengan satu kaki. 2. Kaki yang sama dipakai menumpu berulang-ulang. 3. Contohnya saat bermain engklek." },
{ q: "Merangkak termasuk gerak lokomotor karena...", options: ["Tubuh berpindah tempat", "Dilakukan sambil duduk", "Tubuh diam di tempat", "Hanya tangan yang bergerak"], answer: 0, solution: "1. Ciri gerak lokomotor adalah tubuh berpindah tempat. 2. Saat merangkak, tubuh bergerak maju dengan tangan dan lutut. 3. Jadi merangkak termasuk gerak lokomotor." },
{ q: "Saat memanjat, anggota tubuh yang paling berperan adalah...", options: ["Tangan dan kaki yang saling bergantian", "Hanya perut", "Hanya punggung", "Hanya kepala"], answer: 0, solution: "1. Memanjat butuh pegangan dan pijakan yang kuat. 2. Tangan memegang sedangkan kaki mendorong tubuh ke atas. 3. Keduanya bekerja bergantian supaya tidak jatuh." },
{ q: "Membungkukkan badan ke depan termasuk gerak...", options: ["Manipulatif", "Kombinasi", "Lokomotor", "Nonlokomotor"], answer: 3, solution: "1. Saat membungkuk, kaki tidak berpindah tempat. 2. Gerak yang tidak memindahkan tubuh disebut nonlokomotor. 3. Contoh lainnya adalah meliukkan badan dan menekuk lutut." },
{ q: "Menekuk lutut di tempat termasuk gerak nonlokomotor karena...", options: ["Dilakukan berkelompok", "Tubuh berlari cepat", "Tubuh tidak berpindah tempat", "Ada bola yang dilempar"], answer: 2, solution: "1. Ciri nonlokomotor adalah tubuh tetap di tempat. 2. Saat menekuk lutut, posisi kaki tidak berpindah. 3. Jadi gerakannya termasuk nonlokomotor." },
{ q: "Memutar kepala ke kanan dan ke kiri termasuk gerak...", options: ["Lokomotor", "Manipulatif", "Nonlokomotor", "Estafet"], answer: 2, solution: "1. Kepala bergerak tetapi badan tetap di tempat. 2. Gerak tanpa berpindah tempat disebut nonlokomotor. 3. Gerakan ini bagus untuk pemanasan leher." },
{ q: "Mengayunkan kaki ke depan dan ke belakang tanpa berpindah tempat termasuk gerak...", options: ["Manipulatif", "Kombinasi", "Lokomotor", "Nonlokomotor"], answer: 3, solution: "1. Kaki berayun tetapi tubuh tidak pindah tempat. 2. Gerak yang tidak memindahkan tubuh disebut nonlokomotor. 3. Jadi jawabannya nonlokomotor." },
{ q: "Gerakan memilin badan (memutar tubuh ke samping) termasuk gerak...", options: ["Lokomotor", "Estafet", "Manipulatif", "Nonlokomotor"], answer: 3, solution: "1. Memilin badan dilakukan dengan posisi kaki tetap. 2. Karena tubuh tidak berpindah tempat, gerakannya nonlokomotor. 3. Gerakan ini melatih kelenturan pinggang." },
{ q: "Contoh gerak nonlokomotor saat pemanasan adalah...", options: ["Melempar bola jauh", "Membungkuk menyentuh ujung kaki", "Menangkap bola", "Berlari keliling lapangan"], answer: 1, solution: "1. Membungkuk menyentuh ujung kaki dilakukan di tempat. 2. Gerak di tempat tanpa berpindah disebut nonlokomotor. 3. Gerakan ini meregangkan otot kaki dan punggung." },
{ q: "Agar lemparan bola bisa jauh ke depan, lengan harus...", options: ["Digerakkan pelan-pelan", "Ditekuk diam di samping badan", "Disembunyikan di belakang", "Diayun kuat dari belakang ke depan"], answer: 3, solution: "1. Lemparan jauh butuh tenaga ayunan lengan yang besar. 2. Lengan diayun dari belakang ke depan dengan cepat. 3. Badan ikut condong ke depan saat melepaskan bola." },
{ q: "Melempar bola kepada teman yang berdiri dekat sebaiknya dilakukan dengan...", options: ["Lemparan pelan dan terarah", "Lemparan sambil menutup mata", "Lemparan setinggi-tingginya", "Lemparan sekuat tenaga"], answer: 0, solution: "1. Teman yang dekat tidak butuh tenaga besar. 2. Lemparan pelan lebih mudah ditangkap teman. 3. Arahkan bola tepat ke tangan teman." },
{ q: "Saat menggiring bola dalam sepak bola, bola harus...", options: ["Dibiarkan menggelinding sendiri", "Diinjak sampai berhenti", "Ditendang sekuat tenaga ke depan", "Dekat dengan kaki dan didorong pelan-pelan"], answer: 3, solution: "1. Menggiring artinya membawa bola sambil bergerak. 2. Bola didorong pelan dengan kaki bagian dalam atau luar. 3. Bola yang dekat dengan kaki tidak mudah direbut lawan." },
{ q: "Saat menggiring bola basket, bola dipantulkan dengan...", options: ["Lutut", "Kepalan tangan", "Ujung jari-jari tangan", "Siku"], answer: 2, solution: "1. Pantulan bola dikontrol dengan ujung jari. 2. Ujung jari membuat pantulan bola stabil dan terarah. 3. Kepalan tangan membuat bola sulit dikendalikan." },
{ q: "Menangkap bola yang melambung tinggi dilakukan dengan...", options: ["Menendang bola", "Kedua tangan di atas kepala membentuk wadah", "Satu tangan di belakang punggung", "Menutup mata dan diam"], answer: 1, solution: "1. Bola yang melambung datang dari atas. 2. Kedua tangan diangkat membentuk wadah di atas kepala. 3. Tangan yang membentuk wadah membuat bola tidak lepas." },
{ q: "Saat memukul bola kasti, pandangan mata harus tertuju pada...", options: ["Penonton", "Teman di belakang", "Bola yang datang", "Tiupan angin"], answer: 2, solution: "1. Bola kasti datang dengan cepat setelah dilambungkan. 2. Mata yang fokus pada bola membuat pukulan tepat. 3. Kalau melihat ke lain arah, pukulan bisa meleset." },
{ q: "Lompat jauh diawali dengan gerakan...", options: ["Lari awalan yang cepat", "Duduk diam", "Berdiri mematung", "Berjalan mundur"], answer: 0, solution: "1. Lompat jauh butuh kecepatan sebelum melompat. 2. Pelompat berlari kencang sebagai awalan. 3. Kecepatan lari diubah menjadi lompatan yang jauh." },
{ q: "Berlari lalu melompat adalah kombinasi gerak...", options: ["Manipulatif dan manipulatif", "Diam dan tidur", "Nonlokomotor dan manipulatif", "Lokomotor dan lokomotor"], answer: 3, solution: "1. Berlari adalah gerak lokomotor. 2. Melompat juga gerak lokomotor. 3. Keduanya berpindah tempat sehingga kombinasinya lokomotor dan lokomotor." },
{ q: "Berjalan sambil melempar bola termasuk kombinasi gerak...", options: ["Nonlokomotor saja", "Diam di tempat", "Hanya manipulatif", "Lokomotor dan manipulatif"], answer: 3, solution: "1. Berjalan membuat tubuh berpindah tempat sehingga termasuk lokomotor. 2. Melempar memakai alat yaitu bola sehingga termasuk manipulatif. 3. Jadi gerakannya kombinasi lokomotor dan manipulatif." },
{ q: "Melompat untuk menangkap bola adalah kombinasi gerak...", options: ["Tidur dan duduk", "Manipulatif dan nonlokomotor", "Diam dan jongkok", "Lokomotor dan manipulatif"], answer: 3, solution: "1. Melompat memindahkan tubuh sehingga termasuk lokomotor. 2. Menangkap memakai benda yaitu bola sehingga termasuk manipulatif. 3. Jadi gerakannya kombinasi lokomotor dan manipulatif." },
{ q: "Dalam permainan kasti, memukul bola lalu berlari ke tiang hinggap adalah kombinasi gerak...", options: ["Lokomotor dan manipulatif", "Diam di tempat", "Nonlokomotor saja", "Manipulatif dan manipulatif"], answer: 0, solution: "1. Memukul bola memakai alat sehingga termasuk manipulatif. 2. Berlari ke tiang hinggap memindahkan tubuh sehingga termasuk lokomotor. 3. Jadi gerakannya kombinasi manipulatif dan lokomotor." },
{ q: "Tendangan sudut diberikan ketika...", options: ["Kiper menangkap bola", "Bola keluar garis samping", "Terjadi pelanggaran di tengah lapangan", "Bola keluar garis gawang dan terakhir disentuh pemain bertahan"], answer: 3, solution: "1. Tendangan sudut terjadi di dekat gawang. 2. Penyebabnya bola melewati garis gawang karena sentuhan pemain bertahan. 3. Bola diletakkan di sudut lapangan untuk ditendang." },
{ q: "Tendangan sudut dilakukan dari...", options: ["Garis samping", "Tengah lapangan", "Depan gawang sendiri", "Titik sudut lapangan"], answer: 3, solution: "1. Namanya saja tendangan sudut. 2. Bola diletakkan di area sudut lapangan. 3. Pemain menendangnya ke arah gawang lawan." },
{ q: "Lemparan ke dalam terjadi ketika bola...", options: ["Disentuh wasit", "Masuk ke gawang", "Keluar melewati garis samping lapangan", "Ditangkap kiper"], answer: 2, solution: "1. Garis samping adalah batas kiri dan kanan lapangan. 2. Jika bola melewatinya, permainan dimulai lagi dengan lemparan. 3. Tim lawan dari yang terakhir menyentuh bola yang melempar." },
{ q: "Lemparan ke dalam dilakukan dengan cara...", options: ["Ditendang dengan kaki", "Kedua tangan memegang bola dari belakang kepala", "Disundul", "Satu tangan dilempar ke samping"], answer: 1, solution: "1. Aturannya bola dilempar memakai dua tangan. 2. Kedua tangan membawa bola dari belakang kepala. 3. Kedua kaki harus tetap menjejak tanah saat melempar." },
{ q: "Tendangan penalti diberikan karena terjadi pelanggaran di...", options: ["Kotak penalti", "Luar stadion", "Tengah lapangan", "Garis samping"], answer: 0, solution: "1. Kotak penalti adalah area di depan gawang. 2. Pelanggaran di area ini sangat merugikan tim bertahan. 3. Hukumannya tendangan bebas dari titik penalti tanpa halangan pemain lain." },
{ q: "Tendangan penalti hanya dihadapi oleh...", options: ["Semua pemain lawan", "Wasit", "Kiper saja", "Penonton"], answer: 2, solution: "1. Saat penalti, pemain lain harus di luar kotak penalti. 2. Hanya kiper yang boleh menjaga gawang. 3. Penendang berhadapan satu lawan satu dengan kiper." },
{ q: "Kartu kuning dari wasit artinya...", options: ["Pemain harus keluar lapangan", "Peringatan atas pelanggaran", "Hadiah untuk pemain terbaik", "Permainan selesai"], answer: 1, solution: "1. Wasit memberi kartu kuning untuk pelanggaran yang tidak terlalu berat. 2. Kartu kuning adalah peringatan keras bagi pemain. 3. Dua kartu kuning berubah menjadi kartu merah." },
{ q: "Pemain yang mendapat kartu merah harus...", options: ["Istirahat sebentar lalu masuk lagi", "Pindah menjadi kiper", "Keluar lapangan dan tidak boleh diganti", "Duduk di bangku cadangan"], answer: 2, solution: "1. Kartu merah adalah hukuman pelanggaran berat. 2. Pemain harus segera keluar dari lapangan. 3. Timnya bermain dengan jumlah pemain lebih sedikit." },
{ q: "Jika satu pemain terkena kartu merah, timnya bermain dengan...", options: ["10 orang", "9 orang", "11 orang", "12 orang"], answer: 0, solution: "1. Sepak bola normal dimainkan 11 lawan 11. 2. Pemain kena kartu merah keluar dan tak boleh diganti. 3. Jadi timnya tinggal bermain dengan 10 orang." },
{ q: "Pemain dinyatakan offside jika menerima bola saat...", options: ["Menjadi kiper", "Berdiri di lapangan sendiri", "Menendang bola ke belakang", "Berada lebih dekat ke gawang lawan daripada pemain bertahan lawan"], answer: 3, solution: "1. Offside terjadi di daerah lawan. 2. Pemain tidak boleh menunggu bola di belakang pertahanan lawan. 3. Ia harus sejajar atau di belakang pemain bertahan lawan saat bola ditendang teman." },
{ q: "Tugas utama penyerang (striker) dalam sepak bola adalah...", options: ["Menjadi wasit", "Mengatur lampu stadion", "Mencetak gol ke gawang lawan", "Menjaga gawang sendiri"], answer: 2, solution: "1. Penyerang bermain paling dekat dengan gawang lawan. 2. Tugasnya menyelesaikan serangan menjadi gol. 3. Karena itu penyerang harus pandai menendang bola." },
{ q: "Tugas gelandang dalam sepak bola adalah...", options: ["Menghubungkan pertahanan dan serangan", "Mengambil bola dari luar lapangan", "Hanya menjaga gawang", "Menjadi penonton"], answer: 0, solution: "1. Gelandang bermain di tengah lapangan. 2. Ia membantu bek bertahan dan membantu penyerang menyerang. 3. Jadi gelandang adalah penghubung seluruh tim." },
{ q: "Tugas bek dalam sepak bola adalah...", options: ["Mengatur skor pertandingan", "Menghalau serangan lawan dan menjaga daerah pertahanan", "Mencetak gol sebanyak-banyaknya", "Menangkap bola dengan tangan di mana saja"], answer: 1, solution: "1. Bek bermain di dekat gawang sendiri. 2. Tugasnya menghentikan pemain lawan yang menyerang. 3. Bek yang baik membuat gawang sulit dibobol." },
{ q: "Kiper boleh menangkap bola dengan tangan hanya di...", options: ["Kotak penalti timnya sendiri", "Tengah lapangan", "Kotak penalti lawan", "Luar stadion"], answer: 0, solution: "1. Kiper adalah satu-satunya pemain yang boleh memakai tangan. 2. Izin itu hanya berlaku di kotak penalti sendiri. 3. Di luar kotak penalti, kiper sama seperti pemain lain." },
{ q: "Handsball terjadi ketika pemain selain kiper...", options: ["Menendang bola dengan kaki", "Menyundul bola", "Sengaja menyentuh bola dengan tangan", "Berlari cepat"], answer: 2, solution: "1. Sepak bola dimainkan terutama dengan kaki. 2. Menyentuh bola dengan tangan adalah pelanggaran. 3. Hukumannya tendangan bebas untuk lawan." },
{ q: "Tendangan gawang dilakukan ketika bola keluar garis gawang dan terakhir disentuh...", options: ["Wasit", "Pemain penyerang lawan", "Bola cadangan", "Kiper sendiri"], answer: 1, solution: "1. Jika penyerang lawan yang membuat bola keluar, tidak terjadi gol. 2. Permainan dimulai lagi oleh tim bertahan. 3. Kiper atau bek menendang bola dari depan gawang." },
{ q: "Gol dinyatakan sah jika bola...", options: ["Mengenai tiang lalu keluar", "Keluar lapangan", "Melewati garis gawang di antara dua tiang", "Dipegang kiper"], answer: 2, solution: "1. Gawang dibatasi dua tiang dan mistar. 2. Bola harus masuk melewati garis di antara tiang. 3. Seluruh bagian bola harus melewati garis gawang." },
{ q: "Lapangan sepak bola berbentuk...", options: ["Persegi panjang", "Bintang", "Lingkaran", "Segitiga"], answer: 0, solution: "1. Lapangan sepak bola memanjang ke depan. 2. Bentuknya persegi panjang dengan gawang di dua sisi pendek. 3. Ukuran panjangnya lebih besar daripada lebarnya." },
{ q: "Bagian kaki yang tepat untuk menendang bola jauh dan keras adalah...", options: ["Ujung jari kaki", "Tumit saja", "Punggung kaki", "Lutut"], answer: 2, solution: "1. Punggung kaki adalah bagian atas kaki yang lebar. 2. Menendang dengan punggung kaki memberi tenaga besar. 3. Ujung jari kaki mudah cedera jika dipakai menendang keras." },
{ q: "Mengoper bola dengan kaki bagian dalam membuat bola...", options: ["Terarah dan mudah diterima teman", "Berhenti di tempat", "Melambung sangat tinggi", "Berputar-putar tidak jelas"], answer: 0, solution: "1. Kaki bagian dalam bidangnya lebar dan datar. 2. Bola yang ditendang meluncur lurus ke arah teman. 3. Operan seperti ini paling mudah dikontrol penerima." },
{ q: "Berlari zig-zag termasuk gerak lokomotor karena...", options: ["Tidak ada gerakan sama sekali", "Hanya kepala yang bergerak", "Tubuh berpindah tempat berbelok-belok", "Tubuh diam di tempat"], answer: 2, solution: "1. Zig-zag artinya berlari berbelok ke kiri dan kanan. 2. Tubuh tetap berpindah dari satu tempat ke tempat lain. 3. Ciri berpindah tempat membuat gerakannya lokomotor." },
{ q: "Menangkap bola yang menggelinding di tanah dilakukan dengan...", options: ["Badan membungkuk dan tangan membentuk wadah di depan", "Berlari menjauh", "Berdiri tegak dan menutup mata", "Melompat tinggi"], answer: 0, solution: "1. Bola yang menggelinding berada dekat tanah. 2. Badan dibungkukkan agar tangan mencapai bola. 3. Tangan membentuk wadah supaya bola tidak lolos." },
{ q: "Mengangkat lutut tinggi-tinggi di tempat termasuk gerak...", options: ["Nonlokomotor", "Lokomotor", "Manipulatif", "Renang"], answer: 0, solution: "1. Lutut diangkat tetapi kaki tidak berpindah tempat. 2. Gerak tanpa berpindah tempat disebut nonlokomotor. 3. Gerakan ini bagus untuk pemanasan paha." },
{ q: "Melompat seperti katak dari posisi jongkok menggunakan tumpuan...", options: ["Satu kaki saja", "Tangan", "Dua kaki yang menolak bersamaan", "Dagu"], answer: 2, solution: "1. Katak melompat dengan kedua kaki belakangnya. 2. Dua kaki menolak tanah secara bersamaan. 3. Tolakan dua kaki disebut gerakan meloncat." },
{ q: "Duduk lalu berdiri dari kursi termasuk gerak...", options: ["Nonlokomotor", "Lokomotor", "Manipulatif", "Estafet"], answer: 0, solution: "1. Saat duduk lalu berdiri, posisi tubuh tidak berpindah tempat. 2. Gerak yang tidak memindahkan tubuh disebut nonlokomotor. 3. Gerakan ini melatih kekuatan otot kaki." },
{ q: "Servis bawah dalam bola voli dilakukan dengan cara...", options: ["Menendang bola melewati net", "Melompat lalu memukul bola sekerasnya", "Memukul bola dari bawah dengan satu tangan", "Mendorong bola dengan dua tangan dari atas"], answer: 2, solution: "1. Pada servis bawah, bola dipegang satu tangan di depan badan. 2. Tangan satunya mengepal lalu mengayun dari bawah ke depan. 3. Bola dipukul dari bawah agar melambung melewati net." },
{ q: "Servis atas dalam bola voli dilakukan dengan cara...", options: ["Bola dilambungkan lalu dipukul dengan telapak tangan dari atas", "Bola digulingkan di lantai", "Bola ditendang", "Bola dilempar dengan dua tangan dari belakang kepala"], answer: 0, solution: "1. Servis atas diawali bola dilambungkan ke atas. 2. Telapak tangan memukul bola di titik tertinggi. 3. Pukulan dari atas membuat bola meluncur cepat ke lapangan lawan." },
{ q: "Saat passing bawah, bola mengenai...", options: ["Ujung jari", "Lengan bawah yang dirapatkan", "Siku", "Telapak tangan"], answer: 1, solution: "1. Passing bawah memakai kedua lengan yang diluruskan dan dirapatkan. 2. Bola dipantulkan dengan lengan bawah. 3. Perkenaan yang tepat membuat bola melambung terarah ke teman." },
{ q: "Passing atas dilakukan dengan...", options: ["Lengan bawah", "Dada", "Punggung", "Ujung jari kedua tangan di depan dahi"], answer: 3, solution: "1. Kedua tangan diangkat membentuk mangkuk di depan dahi. 2. Bola didorong dengan ujung jari-jari tangan. 3. Lutut sedikit ditekuk lalu diluruskan saat mendorong bola." },
{ q: "Tujuan smash dalam bola voli adalah...", options: ["Mematikan bola dengan pukulan keras menukik", "Mengoper bola ke teman", "Menahan bola di net", "Mengembalikan bola pelan"], answer: 0, solution: "1. Smash adalah pukulan keras dari atas net. 2. Bola dipukul menukik tajam ke lapangan lawan. 3. Pukulan yang keras dan menukik sulit dikembalikan lawan sehingga menghasilkan poin." },
{ q: "Block (bendungan) dalam bola voli dilakukan di...", options: ["Luar lapangan", "Bangku cadangan", "Belakang lapangan", "Depan net dengan kedua tangan diangkat"], answer: 3, solution: "1. Block bertujuan menahan smash lawan. 2. Pemain melompat di depan net sambil mengangkat kedua tangan tinggi. 3. Tangan yang tinggi menjadi dinding penghalang bola." },
{ q: "Rotasi pemain bola voli berputar ke arah...", options: ["Berlawanan jarum jam", "Acak", "Tidak berputar", "Searah jarum jam"], answer: 3, solution: "1. Setiap tim mendapat giliran servis, posisi pemain bergeser. 2. Pergeseran selalu searah jarum jam. 3. Rotasi membuat semua pemain bergantian berada di posisi depan dan belakang." },
{ q: "Dalam permainan bola voli, pemain tidak boleh...", options: ["Menyentuh net saat bermain", "Melompat untuk smash", "Berteriak memberi semangat", "Memukul bola melewati net"], answer: 0, solution: "1. Net adalah pembatas lapangan yang harus dijaga. 2. Tubuh pemain dilarang menyentuh net saat bola hidup. 3. Pelanggaran ini membuat poin diberikan kepada lawan." },
{ q: "Fungsi net dalam permainan bola voli adalah...", options: ["Pengganti bola", "Tempat duduk pemain", "Pembatas lapangan antara dua tim", "Alat pemukul bola"], answer: 2, solution: "1. Net dipasang di tengah lapangan. 2. Net memisahkan daerah permainan dua tim. 3. Bola harus melewati atas net agar permainan sah." },
{ q: "Servis dinyatakan baik jika bola...", options: ["Melewati net dan masuk lapangan lawan", "Keluar lapangan", "Jatuh di lapangan sendiri", "Menyangkut di net"], answer: 0, solution: "1. Servis adalah pukulan pembuka permainan. 2. Bola harus terbang melewati atas net. 3. Bola yang masuk lapangan lawan membuat permainan berlanjut." },
{ q: "Pemain yang melakukan servis berdiri di...", options: ["Tengah lapangan", "Belakang garis lapangan", "Depan net", "Luar stadion"], answer: 1, solution: "1. Servis dilakukan untuk memulai permainan. 2. Pemain berdiri di belakang garis belakang lapangan. 3. Bola dipukul melewati net ke daerah lawan." },
{ q: "Jika satu tim menyentuh bola 4 kali berturut-turut, maka...", options: ["Mendapat 2 poin", "Terjadi pelanggaran dan poin untuk lawan", "Permainan diulang", "Wasit memberi kartu"], answer: 1, solution: "1. Aturan bola voli membatasi maksimal 3 sentuhan. 2. Sentuhan keempat adalah pelanggaran. 3. Poin diberikan kepada tim lawan." },
{ q: "Chest pass dalam bola basket dilakukan dari...", options: ["Samping badan", "Atas kepala", "Depan dada dengan dua tangan", "Belakang punggung"], answer: 2, solution: "1. Chest artinya dada. 2. Bola dipegang dua tangan di depan dada. 3. Kedua lengan diluruskan mendorong bola ke teman." },
{ q: "Bounce pass adalah operan dengan cara...", options: ["Dilempar langsung tanpa menyentuh lantai", "Dipantulkan ke lantai dulu baru ke teman", "Dilempar ke atas tinggi", "Ditendang"], answer: 1, solution: "1. Bounce artinya memantul. 2. Bola dipantulkan ke lantai di antara pengoper dan penerima. 3. Pantulan membuat bola sulit dicegat lawan yang tinggi." },
{ q: "Overhead pass dilakukan dari...", options: ["Depan dada", "Atas kepala dengan dua tangan", "Bawah lutut", "Belakang badan"], answer: 1, solution: "1. Overhead artinya di atas kepala. 2. Bola dipegang dua tangan di atas kepala. 3. Bola didorong ke depan dengan lecutan pergelangan tangan." },
{ q: "Lay-up dalam bola basket dilakukan dengan...", options: ["Melempar bola ke penonton", "Berdiri diam menembak", "Menembak dari tengah lapangan", "Melangkah lalu melompat memasukkan bola ke ring"], answer: 3, solution: "1. Lay-up diawali menggiring bola mendekati ring. 2. Pemain melangkah dua langkah lalu melompat. 3. Bola didorong pelan masuk ke ring dari dekat." },
{ q: "Tembakan bebas (free throw) yang masuk bernilai...", options: ["4 poin", "1 poin", "2 poin", "3 poin"], answer: 1, solution: "1. Free throw diberikan karena pelanggaran lawan. 2. Penembak menembak tanpa dijaga dari garis bebas. 3. Setiap bola yang masuk hanya bernilai 1 poin." },
{ q: "Tembakan yang masuk dari dalam garis tiga angka bernilai...", options: ["5 poin", "1 poin", "2 poin", "3 poin"], answer: 2, solution: "1. Garis tiga angka adalah garis lengkung jauh dari ring. 2. Tembakan dari dalam garis ini lebih dekat. 3. Bola yang masuk bernilai 2 poin." },
{ q: "Pivot dalam bola basket dilakukan dengan...", options: ["Berlari memutari lapangan", "Satu kaki sebagai tumpuan sedangkan kaki lain berputar", "Melompat tinggi", "Berguling di lantai"], answer: 1, solution: "1. Pivot berguna untuk melindungi bola dari lawan. 2. Satu kaki tetap menjejak lantai sebagai tumpuan. 3. Kaki yang lain melangkah memutar ke segala arah." },
{ q: "Rebound adalah gerakan...", options: ["Melakukan pelanggaran", "Menangkap bola pantulan yang gagal masuk ring", "Melempar bola ke ring", "Menggiring bola cepat"], answer: 1, solution: "1. Tidak semua tembakan masuk ke ring. 2. Bola yang memantul dari papan atau ring diperebutkan. 3. Pemain yang menangkap pantulan itu melakukan rebound." },
{ q: "Travelling terjadi ketika pemain...", options: ["Menembak bola ke ring", "Menggiring bola dengan benar", "Berjalan atau berlari sambil memegang bola tanpa menggiring", "Mengoper bola ke teman"], answer: 2, solution: "1. Pemain yang memegang bola hanya boleh melangkah dua langkah. 2. Melangkah lebih sambil memegang bola tanpa pantulan disebut travelling. 3. Pelanggaran ini membuat bola pindah ke lawan." },
{ q: "Double dribble adalah pelanggaran karena pemain...", options: ["Menembak dua kali", "Menggiring bola terlalu cepat", "Berhenti memegang bola lalu menggiring lagi", "Mengoper bola dua kali"], answer: 2, solution: "1. Menggiring bola boleh berhenti dengan memegang bola. 2. Setelah memegang bola, pemain harus mengoper atau menembak. 3. Menggiring lagi setelah berhenti disebut double dribble." },
{ q: "Permainan bola basket diawali dengan...", options: ["Tendangan penalti", "Wasit melambungkan bola ke atas diperebutkan dua pemain", "Lemparan ke dalam", "Servis"], answer: 1, solution: "1. Awal permainan dua tim berhadapan di tengah lapangan. 2. Wasit melambungkan bola tinggi ke atas. 3. Satu pemain dari tiap tim melompat memperebutkan bola." },
{ q: "Saat menggiring bola basket, bola sebaiknya dipantulkan...", options: ["Setinggi langit-langit", "Tidak dipantulkan", "Setinggi kepala", "Setinggi pinggang ke bawah"], answer: 3, solution: "1. Pantulan yang rendah lebih mudah dikontrol. 2. Bola setinggi pinggang ke bawah sulit direbut lawan. 3. Pantulan terlalu tinggi mudah dicuri lawan." },
{ q: "Teknik melempar bola kasti yang benar adalah...", options: ["Bola dijatuhkan begitu saja", "Lengan diayun dari atas belakang ke depan", "Bola digelindingkan di tanah", "Bola dilempar ke belakang"], answer: 1, solution: "1. Bola kasti dipegang satu tangan di belakang. 2. Lengan diayun dari atas belakang ke depan dengan kuat. 3. Badan ikut condong ke depan saat bola dilepas." },
{ q: "Menangkap bola kasti yang datang mendatar dilakukan dengan...", options: ["Satu kaki", "Kedua tangan membentuk wadah di depan dada", "Menutup mata", "Membelakangi bola"], answer: 1, solution: "1. Bola mendatar datang setinggi dada. 2. Kedua tangan dibuka membentuk wadah di depan dada. 3. Tangan segera menutup saat bola menyentuh tangan." },
{ q: "Saat memukul bola kasti, kayu pemukul diayunkan...", options: ["Mendatar setinggi datangnya bola", "Ke bawah mengenai tanah", "Diputar-putar di atas kepala", "Ke atas setinggi langit"], answer: 0, solution: "1. Bola kasti dilambungkan setinggi pinggang atau dada. 2. Pemukul diayun mendatar mengikuti tinggi bola. 3. Ayunan mendatar membuat pukulan tepat mengenai bola." },
{ q: "Fungsi tiang hinggap dalam permainan kasti adalah...", options: ["Tiang bendera", "Tempat duduk penonton", "Tempat pemain berhenti berlindung setelah memukul", "Tempat menyimpan bola"], answer: 2, solution: "1. Setelah memukul bola, pemain berlari mengelilingi lapangan. 2. Tiang hinggap adalah pos pemberhentian yang aman. 3. Pemain yang sampai di tiang hinggap tidak bisa dimatikan." },
{ q: "Regu pemukul dan regu penjaga bertukar peran setelah...", options: ["Satu pemain memukul", "Semua pemain regu pemukul mendapat giliran memukul", "Wasit meniup peluit sekali", "Bola hilang"], answer: 1, solution: "1. Permainan kasti dimainkan dua regu bergantian. 2. Setiap pemain regu pemukul diberi kesempatan memukul. 3. Setelah semua mendapat giliran, peran ditukar." },
{ q: "Pemain regu pemukul dinyatakan mati jika...", options: ["Memukul bola sangat jauh", "Berhasil sampai di tiang hinggap", "Badannya terkena lemparan bola regu penjaga", "Berlari sangat cepat"], answer: 2, solution: "1. Regu penjaga berusaha mematikan pelari. 2. Caranya melempar bola mengenai badan pelari. 3. Pelari yang terkena lemparan dinyatakan mati dan keluar." },
{ q: "Tugas regu penjaga dalam permainan kasti adalah...", options: ["Menjadi penonton", "Memukul bola sejauh mungkin", "Menangkap bola dan mematikan lawan", "Berlari ke tiang hinggap"], answer: 2, solution: "1. Regu penjaga menyebar di lapangan. 2. Mereka menangkap bola hasil pukulan lawan. 3. Bola itu dipakai untuk mematikan pelari lawan." },
{ q: "Pemukul kasti berdiri di...", options: ["Atas tiang hinggap", "Luar lapangan", "Tengah lapangan", "Ruang pemukul yang sudah ditentukan"], answer: 3, solution: "1. Setiap pemukul punya tempat khusus memukul. 2. Ruang pemukul berada di dekat pelambung. 3. Memukul dari ruang ini membuat permainan tertib." },
{ q: "Regu yang memukul lebih dulu dalam kasti ditentukan dengan...", options: ["Dipilih wasit seenaknya", "Undian atau suit", "Siapa yang paling tinggi", "Siapa yang datang terlambat"], answer: 1, solution: "1. Kedua regu punya hak yang sama. 2. Undian atau suit adalah cara adil menentukan giliran. 3. Pemenang undian boleh memilih memukul atau menjaga lebih dulu." },
{ q: "Lapangan permainan kasti berbentuk...", options: ["Segitiga", "Bulat telur", "Lingkaran", "Persegi panjang"], answer: 3, solution: "1. Lapangan kasti memanjang. 2. Bentuknya persegi panjang dengan tiang hinggap di sudut-sudutnya. 3. Bentuk ini memberi ruang berlari bagi regu pemukul." },
{ q: "Permainan rounders dimainkan oleh...", options: ["Tiga regu sekaligus", "Tanpa regu", "Satu regu saja", "Dua regu yang bergantian memukul dan menjaga"], answer: 3, solution: "1. Rounders adalah permainan beregu. 2. Dua regu bergantian menjadi pemukul dan penjaga. 3. Kerja sama regu menentukan kemenangan." },
{ q: "Fungsi base dalam permainan rounders adalah...", options: ["Tempat persinggahan pelari yang harus diinjak", "Tempat menyimpan tongkat", "Hiasan lapangan", "Tempat duduk wasit"], answer: 0, solution: "1. Setelah memukul, pemain berlari mengelilingi lapangan. 2. Base adalah titik yang wajib diinjak pelari. 3. Pelari yang menginjak semua base dengan selamat mendapat poin." },
{ q: "Tongkat pemukul rounders terbuat dari...", options: ["Kayu", "Kaca", "Kertas", "Plastik tipis"], answer: 0, solution: "1. Tongkat pemukul harus kuat menahan pukulan. 2. Kayu adalah bahan yang kuat dan aman. 3. Tongkat kayu tidak mudah patah saat memukul bola." },
{ q: "Dalam rounders, bola dipukul setelah...", options: ["Dimasukkan ke saku", "Dilempar ke udara oleh pelambung", "Diletakkan di tanah", "Dipegang wasit"], answer: 1, solution: "1. Pelambung bertugas memberi umpan bola. 2. Bola dilambungkan ke arah pemukul. 3. Pemukul mengayunkan tongkat saat bola melambung tiba." },
{ q: "Pelari rounders dinyatakan selamat jika...", options: ["Sampai di base sebelum bola dikuasai penjaga", "Berlari paling cepat", "Berteriak paling keras", "Memukul paling jauh"], answer: 0, solution: "1. Penjaga berusaha mematikan pelari dengan bola. 2. Pelari beradu cepat mencapai base. 3. Pelari yang menginjak base lebih dulu dinyatakan selamat." },
{ q: "Tugas regu penjaga dalam rounders adalah...", options: ["Memukul bola", "Menangkap bola untuk mematikan pelari lawan", "Berlari mengelilingi base", "Duduk menonton"], answer: 1, solution: "1. Regu penjaga menyebar menjaga lapangan. 2. Mereka menangkap bola pukulan lawan. 3. Bola itu digunakan untuk mematikan pelari sebelum sampai base." },
{ q: "Bola voli terutama dimainkan dengan...", options: ["Kaki", "Tangan dan lengan", "Kepala saja", "Siku saja"], answer: 1, solution: "1. Bola voli adalah permainan bola tangan. 2. Bola dipukul, didorong, dan ditahan dengan tangan. 3. Menendang bola adalah pelanggaran." },
{ q: "Tim mendapat poin dalam bola voli ketika...", options: ["Pemain beristirahat", "Bola jatuh di lapangan sendiri", "Bola jatuh di lapangan lawan", "Wasit meniup peluit"], answer: 2, solution: "1. Setiap rally diperebutkan kedua tim. 2. Tim yang membuat bola jatuh di lapangan lawan mendapat poin. 3. Tim yang gagal mengembalikan bola kehilangan poin." },
{ q: "Dalam bola basket, pemain tidak boleh...", options: ["Mengoper bola", "Menembak bola", "Menggiring bola", "Menendang bola"], answer: 3, solution: "1. Bola basket dimainkan dengan tangan. 2. Menendang bola adalah pelanggaran. 3. Bola yang ditendang diberikan kepada lawan." },
{ q: "Jika bola basket keluar lapangan, permainan dilanjutkan dengan...", options: ["Tendangan penalti", "Servis", "Tendangan sudut", "Lemparan ke dalam oleh tim yang tidak terakhir menyentuh bola"], answer: 3, solution: "1. Bola keluar berarti melewati garis lapangan. 2. Tim yang tidak terakhir menyentuh bola mendapat hak. 3. Permainan dilanjutkan dengan lemparan ke dalam." },
{ q: "Tembakan ke arah ring dalam bola basket disebut...", options: ["Pukulan", "Tendangan", "Tembakan (shooting)", "Lemparan lembing"], answer: 2, solution: "1. Tujuan permainan basket adalah memasukkan bola ke ring. 2. Usaha memasukkan bola disebut tembakan atau shooting. 3. Tembakan yang masuk menghasilkan poin." },
{ q: "Bola kasti berukuran...", options: ["Sebesar balon", "Sebesar bola sepak", "Kecil seukuran bola tenis", "Sebesar bola basket"], answer: 2, solution: "1. Bola kasti dirancang untuk dilempar dan dipukul anak. 2. Ukurannya kecil seukuran bola tenis. 3. Bola kecil lebih mudah digenggam dan dilempar jauh." },
{ q: "Pemukul rounders memegang tongkat dengan...", options: ["Dua tangan", "Kaki", "Gigi", "Satu tangan saja"], answer: 0, solution: "1. Tongkat rounders cukup panjang dan berat. 2. Dua tangan memberi ayunan lebih kuat dan terkendali. 3. Pukulan dua tangan membuat bola melambung jauh." },
{ q: "Saat melakukan block, kedua tangan...", options: ["Diangkat tinggi di depan net", "Disembunyikan di belakang", "Memegang net", "Diturunkan ke bawah"], answer: 0, solution: "1. Block menghadang bola smash lawan. 2. Kedua tangan diangkat tinggi melewati net. 3. Tangan yang tinggi menutup jalan bola ke lapangan sendiri." },
{ q: "Bet dalam tenis meja berfungsi sebagai...", options: ["Alat pemukul bola", "Alas meja", "Pengganti net", "Tempat duduk"], answer: 0, solution: "1. Tenis meja dimainkan dengan bola kecil. 2. Pemain butuh alat untuk memukul bola. 3. Bet yang pipih berlapis karet dipakai memukul bola." },
{ q: "Bola tenis meja berukuran...", options: ["Sebesar bola basket", "Sebesar bola sepak", "Seberat batu", "Kecil dan ringan"], answer: 3, solution: "1. Meja tenis meja tidak terlalu besar. 2. Bola yang dipakai kecil dan ringan agar mudah dipukul. 3. Bola kecil membuat permainan cepat dan seru." },
{ q: "Servis tenis meja yang benar adalah...", options: ["Bola ditendang", "Bola dilempar langsung ke lawan", "Bola dipukul setelah memantul di meja sendiri lalu melewati net", "Bola digelindingkan"], answer: 2, solution: "1. Servis diawali bola dilambungkan dari tangan. 2. Bet memukul bola hingga memantul dulu di meja sendiri. 3. Bola harus melewati net ke meja lawan." },
{ q: "Tengah meja tenis meja dibatasi oleh...", options: ["Tembok", "Tali rafia", "Garis kapur", "Net"], answer: 3, solution: "1. Meja tenis meja dibagi dua sama besar. 2. Pembatasnya adalah net kecil di tengah meja. 3. Bola harus melewati atas net saat dipukul." },
{ q: "Cara memegang bet yang umum seperti...", options: ["Mengepal tinju", "Menggenggam palu", "Berjabat tangan", "Memegang sendok"], answer: 2, solution: "1. Gagang bet digenggam dengan nyaman. 2. Cara paling umum seperti berjabat tangan. 3. Genggaman ini membuat pukulan forehand dan backhand mudah." },
{ q: "Alat untuk memukul kok dalam bulutangkis adalah...", options: ["Raket", "Tongkat", "Kayu pemukul", "Bet"], answer: 0, solution: "1. Kok harus dipukul melewati net yang tinggi. 2. Dibutuhkan alat bergagang panjang dan berjala. 3. Alat itu disebut raket." },
{ q: "Shuttlecock atau kok terbuat dari...", options: ["Besi", "Bulu", "Kayu", "Kaca"], answer: 1, solution: "1. Kok harus ringan agar melambung. 2. Bahan yang ringan adalah bulu atau plastik berbulu. 3. Bulu membuat kok melambat dan mudah dipukul." },
{ q: "Servis bulutangkis dilakukan dengan...", options: ["Pukulan sambil melompat", "Tendangan", "Pukulan dari atas kepala lurus ke depan", "Pukulan dari bawah secara diagonal ke area servis lawan"], answer: 3, solution: "1. Servis bulutangkis memakai pukulan bawah. 2. Kok dipukul menyilang ke kotak servis lawan. 3. Pukulan diagonal membuat servis sah dan terarah." },
{ q: "Pukulan dalam bulutangkis dinyatakan baik jika kok...", options: ["Keluar lapangan", "Jatuh di lapangan sendiri", "Melewati net dan jatuh di lapangan lawan", "Menyangkut di net"], answer: 2, solution: "1. Net membagi lapangan bulutangkis. 2. Kok harus terbang melewati atas net. 3. Kok yang jatuh di lapangan lawan membuat permainan berlanjut." },
{ q: "Pukulan keras menukik dalam bulutangkis disebut...", options: ["Smash", "Servis", "Netting", "Lob"], answer: 0, solution: "1. Smash adalah pukulan menyerang. 2. Kok dipukul keras dari atas menukik tajam. 3. Pukulan ini sulit dikembalikan lawan." },
{ q: "Pukulan lob dalam bulutangkis membuat kok...", options: ["Berhenti di net", "Jatuh di depan net sendiri", "Melambung tinggi ke belakang lapangan lawan", "Menukik tajam"], answer: 2, solution: "1. Lob adalah pukulan bertahan. 2. Kok dipukul melambung tinggi jauh ke belakang. 3. Lawan dipaksa mundur sehingga pemain punya waktu bersiap." },
{ q: "Pegangan raket bulutangkis yang benar membuat pukulan...", options: ["Kuat dan terkendali", "Mengenai tangan sendiri", "Mengenai penonton", "Lemah dan tak terarah"], answer: 0, solution: "1. Raket dipegang seperti berjabat tangan. 2. Genggaman yang pas menyalurkan tenaga ke kok. 3. Pukulan menjadi kuat dan arahnya terkendali." },
{ q: "Lari sprint menggunakan start...", options: ["Jongkok", "Duduk", "Tiduran", "Berdiri"], answer: 0, solution: "1. Sprint adalah lari jarak pendek secepat mungkin. 2. Start jongkok memberi tolakan kaki yang kuat. 3. Tolakan kuat membuat pelari melesat cepat sejak awal." },
{ q: "Urutan aba-aba start jongkok adalah...", options: ["Lari - siap - bersedia", "Siap - bersedia - ya", "Bersedia - siap - ya", "Ya - siap - bersedia"], answer: 2, solution: "1. Aba-aba pertama bersedia artinya masuk posisi jongkok. 2. Aba-aba siap artinya angkat pinggul bersiap lari. 3. Aba-aba ya atau bunyi pistol tanda mulai berlari." },
{ q: "Dalam lari estafet, tongkat diberikan kepada...", options: ["Pelatih", "Penonton", "Pelari berikutnya di zona pergantian", "Wasit"], answer: 2, solution: "1. Lari estafet dimainkan beregu sambung-menyambung. 2. Tongkat dioper ke pelari berikutnya. 3. Pemberian tongkat hanya sah di zona pergantian." },
{ q: "Lari estafet 4x100 meter diikuti oleh...", options: ["4 pelari", "8 pelari", "1 pelari", "2 pelari"], answer: 0, solution: "1. Angka 4 pada 4x100 artinya 4 orang pelari. 2. Setiap pelari berlari 100 meter. 3. Total jarak yang ditempuh tim adalah 400 meter." },
{ q: "Ciri lompat jauh gaya jongkok saat melayang di udara adalah...", options: ["Kedua lutut ditekuk seperti jongkok", "Tangan di saku", "Badan telentang", "Kaki lurus ke depan"], answer: 0, solution: "1. Setelah menolak, pelompat melayang di udara. 2. Pada gaya jongkok kedua lutut ditekuk ke depan. 3. Posisi ini menjaga keseimbangan sebelum mendarat." },
{ q: "Pendaratan lompat jauh yang benar adalah...", options: ["Dengan kepala dulu", "Dengan kedua kaki di bak pasir", "Dengan tangan", "Di luar bak pasir"], answer: 1, solution: "1. Bak pasir disediakan sebagai tempat mendarat. 2. Kedua kaki mendarat bersamaan di pasir. 3. Pasir yang empuk membuat pendaratan aman." },
{ q: "Tolak peluru dilakukan dengan cara...", options: ["Melempar peluru seperti lembing", "Menolak peluru dari dekat bahu dengan satu tangan", "Menendang peluru", "Melempar dengan dua tangan dari atas kepala"], answer: 1, solution: "1. Peluru adalah bola besi yang berat. 2. Peluru ditempelkan dekat bahu atau telinga. 3. Lengan mendorong kuat ke depan, bukan dilempar." },
{ q: "Lempar turbo adalah alat untuk belajar...", options: ["Lari sprint", "Lempar lembing", "Tolak peluru", "Lompat jauh"], answer: 1, solution: "1. Lembing asli tajam dan berbahaya untuk anak. 2. Lempar turbo adalah lembing tiruan yang aman. 3. Anak berlatih teknik melempar dengan turbo." },
{ q: "Kunci sukses lari jarak menengah adalah...", options: ["Berlari sekencang-kencangnya sejak awal", "Mengatur kecepatan dan pernapasan tetap stabil", "Berhenti di tengah jalan", "Berlari sambil menahan napas"], answer: 1, solution: "1. Lari jarak menengah cukup jauh. 2. Tenaga harus dihemat dengan kecepatan stabil. 3. Pernapasan teratur membuat pelari tidak cepat lelah." },
{ q: "Saat mencapai garis finish lari sprint, bagian tubuh yang dicondongkan adalah...", options: ["Kaki", "Tangan", "Kepala", "Dada"], answer: 3, solution: "1. Pemenang ditentukan bagian tubuh yang menyentuh garis dulu. 2. Dada dicondongkan ke depan saat mendekati garis. 3. Condongan dada bisa menentukan kemenangan." },
{ q: "Lari jarak pendek disebut juga...", options: ["Maraton", "Sprint", "Jalan santai", "Lari estafet"], answer: 1, solution: "1. Lari jarak pendek menempuh 60 sampai 100 meter. 2. Pelari berlari sekencang mungkin sejak start. 3. Lari secepat ini disebut sprint." },
{ q: "Sikap lilin bertumpu pada...", options: ["Kepala", "Bahu dan punggung atas dengan tangan menopang pinggang", "Lutut", "Perut"], answer: 1, solution: "1. Sikap lilin diawali tidur telentang. 2. Kedua kaki diangkat lurus ke atas. 3. Tumpuan ada di bahu sedangkan tangan menopang pinggang." },
{ q: "Saat melakukan guling depan, dagu...", options: ["Dibiarkan bebas", "Menoleh ke samping", "Didongakkan ke atas", "Ditempelkan ke dada"], answer: 3, solution: "1. Guling depan diawali jongkok. 2. Dagu ditempel ke dada agar kepala terlindungi. 3. Badan berguling mulus seperti bola." },
{ q: "Guling belakang dilakukan dengan berguling ke arah...", options: ["Depan", "Belakang", "Samping kanan", "Samping kiri"], answer: 1, solution: "1. Guling belakang diawali jongkok membelakangi matras. 2. Badan dijatuhkan berguling ke belakang. 3. Tangan membantu mendorong agar gulingan mulus." },
{ q: "Gerakan kayang bertumpu pada...", options: ["Tangan dan kaki", "Siku dan lutut", "Punggung saja", "Kepala dan lutut"], answer: 0, solution: "1. Kayang diawali tidur telentang. 2. Badan diangkat melengkung ke atas. 3. Tangan dan kaki menjadi tumpuan penahan tubuh." },
{ q: "Berdiri dengan satu kaki melatih...", options: ["Daya ingat", "Kecepatan", "Keseimbangan", "Kekuatan gigi"], answer: 2, solution: "1. Berdiri satu kaki membuat tubuh mudah goyang. 2. Otot-otot bekerja menjaga tubuh tetap tegak. 3. Latihan ini melatih keseimbangan tubuh." },
{ q: "Saat lompat tali, lompatan dilakukan ketika...", options: ["Tali berhenti", "Tali putus", "Tali di atas kepala", "Tali melewati bawah kaki"], answer: 3, solution: "1. Tali diputar melewati tubuh. 2. Saat tali sampai di bawah kaki, badan melompat. 3. Waktu lompat yang tepat membuat tali tidak tersangkut." },
{ q: "Senam lantai sebaiknya dilakukan di atas...", options: ["Aspal", "Kerikil", "Lantai keramik", "Matras yang empuk"], answer: 3, solution: "1. Senam lantai banyak gerakan berguling. 2. Matras empuk melindungi tubuh dari benturan. 3. Latihan di matras lebih aman dan nyaman." },
{ q: "Sikap kapal terbang melatih...", options: ["Kecepatan lari", "Kekuatan gigi", "Kelenturan lidah", "Keseimbangan"], answer: 3, solution: "1. Sikap kapal terbang berdiri satu kaki. 2. Kedua tangan direntangkan ke samping. 3. Posisi ini melatih keseimbangan tubuh." },
{ q: "Ciri renang gaya bebas adalah...", options: ["Berenang mundur", "Diam mengapung saja", "Lengan bergerak bergantian dan wajah menghadap air", "Kedua lengan dibuka seperti katak"], answer: 2, solution: "1. Gaya bebas adalah gaya tercepat. 2. Kedua lengan dikayuh bergantian ke depan. 3. Wajah menghadap air dan menoleh saat mengambil napas." },
{ q: "Renang gaya dada meniru gerakan...", options: ["Ikan paus", "Kuda", "Katak", "Burung"], answer: 2, solution: "1. Gaya dada disebut juga gaya katak. 2. Kedua lengan dibuka ke samping bersamaan. 3. Kaki menendang seperti kaki katak berenang." },
{ q: "Gerakan kaki pada gaya bebas adalah...", options: ["Disilangkan", "Naik turun bergantian", "Diam tidak bergerak", "Dibuka tutup seperti gunting"], answer: 1, solution: "1. Kaki membantu mendorong tubuh maju. 2. Kedua kaki dicambuk naik turun bergantian. 3. Gerakan cepat dan rapat membuat laju stabil." },
{ q: "Anak tidak boleh berenang sendiri karena...", options: ["Berbahaya jika tenggelam tidak ada yang menolong", "Kolamnya sepi", "Tidak ada teman bermain", "Airnya dingin"], answer: 0, solution: "1. Berenang punya risiko tenggelam. 2. Anak belum pandai mengatasi bahaya di air. 3. Harus ada orang dewasa atau pengawas yang menjaga." },
{ q: "Di kolam renang dilarang...", options: ["Memakai kacamata renang", "Bernapas", "Berenang pelan", "Mendorong teman bercanda"], answer: 3, solution: "1. Kolam renang licin dan dalam. 2. Mendorong teman bisa membuatnya tenggelam atau terbentur. 3. Bercanda di kolam sangat berbahaya." },
{ q: "Sebelum berenang sebaiknya...", options: ["Makan banyak", "Tidur dulu", "Langsung terjun", "Pemanasan dulu agar otot tidak kram"], answer: 3, solution: "1. Air kolam lebih dingin dari tubuh. 2. Otot yang kaget bisa kram di air. 3. Pemanasan membuat otot siap dan lentur." },
{ q: "Agar bisa mengapung, tubuh harus...", options: ["Menahan napas sambil menyelam", "Bergerak secepat mungkin", "Tegang dan panik", "Rileks telentang di permukaan air"], answer: 3, solution: "1. Tubuh manusia bisa mengapung di air. 2. Posisi telentang dengan tubuh rileks paling mudah. 3. Kepanikan justru membuat tubuh tenggelam." },
{ q: "Kacamata renang berfungsi...", options: ["Gaya-gayaan saja", "Melindungi mata dari air kolam", "Agar bisa melihat ikan", "Menambah kecepatan"], answer: 1, solution: "1. Air kolam mengandung kaporit. 2. Kaporit membuat mata pedih dan merah. 3. Kacamata melindungi mata sekaligus memudahkan melihat." },
{ q: "Tugas penjaga dalam gobak sodor adalah...", options: ["Menarik tali", "Menghitung biji congklak", "Menghadang lawan yang melewati garis", "Bersembunyi"], answer: 2, solution: "1. Gobak sodor dimainkan dua regu. 2. Penjaga berdiri di garis-garis lapangan. 3. Mereka berusaha menyentuh lawan yang menyelinap lewat." },
{ q: "Cara memenangkan benteng-bentengan adalah...", options: ["Bersembunyi paling lama", "Menyentuh benteng lawan", "Berlari paling cepat", "Berteriak paling keras"], answer: 1, solution: "1. Setiap regu punya benteng sendiri. 2. Pemain menyelinap melewati penjagaan lawan. 3. Regu yang menyentuh benteng lawan lebih dulu menang." },
{ q: "Congklak dimainkan dengan cara...", options: ["Melempar bola", "Menarik tali", "Memindahkan biji-bijian ke lubang papan", "Melompat satu kaki"], answer: 2, solution: "1. Papan congklak punya lubang-lubang kecil. 2. Pemain memindahkan biji satu per satu. 3. Pemain yang mengumpulkan biji terbanyak menang." },
{ q: "Engklek dimainkan dengan cara...", options: ["Menarik tambang", "Melompat dengan satu kaki mengikuti petak", "Berenang", "Bersembunyi"], answer: 1, solution: "1. Engklek digambar petak-petak di tanah. 2. Pemain melompat satu kaki dari petak ke petak. 3. Tidak boleh menginjak garis atau kehilangan keseimbangan." },
{ q: "Dalam petak umpet, pemain yang berjaga bertugas...", options: ["Tidur", "Bernyanyi", "Bersembunyi", "Mencari teman yang bersembunyi"], answer: 3, solution: "1. Satu pemain ditunjuk menjadi penjaga. 2. Penjaga menutup mata sambil menghitung. 3. Setelah itu ia mencari semua teman yang bersembunyi." },
{ q: "Tarik tambang melatih...", options: ["Kelenturan", "Keseimbangan", "Kekuatan dan kekompakan tim", "Kecepatan berlari"], answer: 2, solution: "1. Tarik tambang dimainkan dua tim berhadapan. 2. Kedua tim menarik tali sekuat tenaga. 3. Kemenangan butuh kekuatan dan tarikan yang kompak." },
{ q: "Balap karung dilakukan dengan...", options: ["Berlari biasa", "Kedua kaki masuk karung lalu melompat", "Merangkak", "Berjalan mundur"], answer: 1, solution: "1. Setiap peserta memakai karung di kaki. 2. Kaki tidak bisa melangkah bebas. 3. Peserta melompat-lompat menuju garis finish." },
{ q: "Egrang terbuat dari...", options: ["Kaca", "Bambu panjang", "Plastik tipis", "Kertas"], answer: 1, solution: "1. Egrang adalah permainan berjalan tinggi. 2. Bahannya bambu panjang yang kuat. 3. Pemain berdiri di pijakan bambu lalu berjalan." },
{ q: "Tim tarik tambang dinyatakan menang jika...", options: ["Berteriak paling keras", "Jumlah pemain paling banyak", "Talinya putus", "Menarik tali hingga tanda tengah melewati garis batas timnya"], answer: 3, solution: "1. Tengah tali diberi tanda. 2. Kedua tim menarik berlawanan arah. 3. Tim yang menarik tanda melewati garis batasnya menang." },
{ q: "Tes lari 12 menit bertujuan mengukur...", options: ["Daya tahan jantung dan paru-paru", "Kekuatan tangan", "Kelenturan", "Kecepatan"], answer: 0, solution: "1. Tes ini meminta pelari berlari selama 12 menit. 2. Jarak tempuh dicatat sebagai hasil. 3. Semakin jauh jaraknya, semakin baik daya tahan jantung dan paru." },
{ q: "Latihan back-up melatih otot...", options: ["Punggung", "Kaki", "Leher saja", "Perut"], answer: 0, solution: "1. Back-up diawali tidur telungkup. 2. Dada dan kaki diangkat bergantian ke atas. 3. Gerakan ini menguatkan otot punggung." },
{ q: "Plank dilakukan dengan posisi...", options: ["Berdiri satu kaki", "Tidur telentang", "Tubuh lurus bertumpu pada siku dan ujung kaki", "Duduk bersila"], answer: 2, solution: "1. Plank diawali posisi telungkup. 2. Tubuh diangkat lurus bertumpu siku dan ujung kaki. 3. Tahan posisi ini untuk menguatkan otot perut dan tubuh." },
{ q: "Lari bolak-balik (shuttle run) melatih...", options: ["Kekuatan gigi", "Daya ingat", "Kecepatan membaca", "Kelincahan"], answer: 3, solution: "1. Shuttle run berlari cepat bolak-balik jarak pendek. 2. Pemain harus berbalik arah dengan cepat. 3. Gerakan ini melatih kelincahan tubuh." },
{ q: "Lari zig-zag melatih...", options: ["Kekuatan lengan", "Daya tahan bernyanyi", "Kelenturan lidah", "Kelincahan mengubah arah"], answer: 3, solution: "1. Zig-zag berlari berbelok kiri kanan melewati rintangan. 2. Tubuh harus cepat mengubah arah. 3. Latihan ini melatih kelincahan." },
{ q: "Tes sit and reach mengukur...", options: ["Kekuatan otot", "Berat badan", "Kecepatan", "Kelenturan tubuh"], answer: 3, solution: "1. Sit and reach diawali duduk kaki lurus. 2. Tangan berusaha meraih ujung kaki sejauh mungkin. 3. Jangkauan tangan menunjukkan kelenturan tubuh." },
{ q: "Lompat tegak (vertical jump) mengukur...", options: ["Kekuatan ledakan otot kaki", "Panjang lengan", "Tinggi badan", "Berat badan"], answer: 0, solution: "1. Vertical jump melompat setinggi mungkin dari posisi berdiri. 2. Raihan tangan tertinggi dicatat. 3. Hasilnya menunjukkan kekuatan ledakan otot kaki." },
{ q: "Tes berdiri satu kaki mengukur...", options: ["Kecepatan", "Keseimbangan", "Kekuatan", "Daya tahan"], answer: 1, solution: "1. Peserta berdiri satu kaki selama mungkin. 2. Tubuh berusaha tidak goyang atau jatuh. 3. Lamanya bertahan menunjukkan keseimbangan tubuh." },
{ q: "Tes lari 40 meter mengukur...", options: ["Keseimbangan", "Daya tahan", "Kelenturan", "Kecepatan"], answer: 3, solution: "1. Peserta berlari 40 meter secepat mungkin. 2. Waktu tempuh dicatat dengan stopwatch. 3. Waktu tersingkat menunjukkan kecepatan terbaik." },
{ q: "Karbohidrat berguna bagi tubuh sebagai...", options: ["Sumber energi", "Pembangun tulang", "Pembersih gigi", "Penambah tinggi instan"], answer: 0, solution: "1. Tubuh butuh bahan bakar untuk bergerak. 2. Karbohidrat seperti nasi, roti, dan jagung memberi energi. 3. Energi ini dipakai untuk belajar dan bermain." },
{ q: "Protein berguna untuk...", options: ["Menambah berat air", "Mengurangi nafsu makan", "Pertumbuhan dan membangun tubuh", "Membuat mengantuk"], answer: 2, solution: "1. Tubuh anak sedang tumbuh. 2. Protein dari telur, ikan, dan tempe membangun otot dan sel tubuh. 3. Anak yang cukup protein tumbuh sehat dan kuat." },
{ q: "Vitamin banyak terdapat pada...", options: ["Buah dan sayur", "Minuman bersoda", "Kerupuk", "Permen"], answer: 0, solution: "1. Buah dan sayur kaya vitamin dan mineral. 2. Vitamin menjaga daya tahan tubuh. 3. Anak yang rajin makan buah sayur jarang sakit." },
{ q: "Lima sempurna dalam semboyan 4 sehat 5 sempurna adalah...", options: ["Susu", "Permen", "Kerupuk", "Nasi"], answer: 0, solution: "1. Empat sehat terdiri dari makanan pokok, lauk, sayur, dan buah. 2. Agar sempurna ditambah satu lagi. 3. Tambahannya adalah susu yang baik untuk tulang." },
{ q: "Anak sebaiknya minum air putih...", options: ["Tidak perlu minum", "1 gelas sehari", "8 gelas sehari", "20 gelas sehari"], answer: 2, solution: "1. Tubuh butuh cairan setiap hari. 2. Anjuran untuk anak sekitar 8 gelas sehari. 3. Air putih mencegah dehidrasi dan menjaga tubuh segar." },
{ q: "Jajan sembarangan berbahaya karena...", options: ["Makanan bisa kotor mengandung kuman", "Warnanya menarik", "Temannya banyak", "Makanannya mahal"], answer: 0, solution: "1. Jajanan sembarangan tidak terjamin kebersihannya. 2. Makanan kotor mengandung kuman penyakit. 3. Kuman itu bisa menyebabkan sakit perut dan diare." },
{ q: "Rokok berbahaya bagi tubuh karena...", options: ["Baunya wangi", "Merusak paru-paru dan jantung", "Membuat pintar", "Harganya murah"], answer: 1, solution: "1. Asap rokok mengandung racun. 2. Racun itu merusak paru-paru dan jantung. 3. Anak harus menjauhi rokok dan asapnya." },
{ q: "Begadang tidak baik karena...", options: ["Tubuh kurang istirahat", "Bintang terlihat jelas", "Listrik mahal", "Malam hari sepi"], answer: 0, solution: "1. Tubuh butuh tidur untuk pulih. 2. Begadang memotong waktu tidur. 3. Anak yang begadang bangun lemas dan sulit fokus belajar." },
{ q: "Mencuci tangan yang benar memakai...", options: ["Sabun dan air mengalir", "Pasir", "Tisu kering saja", "Air saja"], answer: 0, solution: "1. Tangan menyentuh banyak benda berkuman. 2. Sabun membunuh kuman di tangan. 3. Bilas dengan air mengalir agar kuman hilang." },
{ q: "Buang air besar sebaiknya dilakukan di...", options: ["Kebun", "Selokan", "Sungai", "Jamban atau WC yang bersih"], answer: 3, solution: "1. Kotoran manusia mengandung kuman penyakit. 2. Buang air di sembarang tempat menyebar penyakit. 3. Jamban bersih menjaga lingkungan sehat." },
{ q: "Kuku harus dipotong rutin karena...", options: ["Kuku panjang menyimpan kuman", "Agar bisa mencakar", "Supaya berwarna", "Agar terlihat panjang"], answer: 0, solution: "1. Kotoran mudah menumpuk di bawah kuku panjang. 2. Kotoran itu menyimpan kuman penyakit. 3. Kuku pendek dan bersih mencegah kuman masuk ke mulut." },
{ q: "Pakaian olahraga yang basah keringat sebaiknya...", options: ["Dijemur sambil dipakai", "Diberikan ke teman", "Dipakai terus seharian", "Segera diganti dengan yang kering"], answer: 3, solution: "1. Keringat membuat pakaian lembap. 2. Pakaian lembap menjadi sarang kuman dan bau. 3. Segera ganti pakaian kering agar tubuh sehat." },
{ q: "Menjaga kebersihan lingkungan dilakukan dengan...", options: ["Membakar sampah plastik sembarangan", "Menumpuk sampah di kelas", "Membuang sampah pada tempatnya", "Membuang sampah ke sungai"], answer: 2, solution: "1. Lingkungan bersih membuat nyaman. 2. Sampah dibuang ke tempat sampah yang tersedia. 3. Kebiasaan ini mencegah banjir dan penyakit." },
{ q: "Setelah berolahraga dan berkeringat sebaiknya...", options: ["Langsung tidur", "Mandi agar tubuh bersih", "Makan permen", "Bermain lagi"], answer: 1, solution: "1. Olahraga membuat tubuh berkeringat. 2. Keringat yang dibiarkan membuat badan bau dan gatal. 3. Mandi membersihkan tubuh dari keringat dan kuman." },
{ q: "Makan yang baik adalah...", options: ["Hanya makan permen", "Tidak makan seharian", "Makan secukupnya dengan gizi seimbang", "Makan sebanyak-banyaknya"], answer: 2, solution: "1. Tubuh butuh makanan bergizi seimbang. 2. Makan secukupnya sesuai kebutuhan tubuh. 3. Makan berlebihan bisa membuat perut sakit dan badan gemuk." },
{ q: "Contoh gerakan pemanasan adalah...", options: ["Duduk diam", "Tidur", "Jogging di tempat", "Push-up 100 kali"], answer: 2, solution: "1. Pemanasan dilakukan sebelum olahraga inti. 2. Jogging di tempat menghangatkan tubuh perlahan. 3. Gerakan ringan ini menyiapkan otot dan jantung." },
{ q: "Contoh peregangan dinamis saat pemanasan adalah...", options: ["Duduk diam menahan kaki", "Mengayun lengan dan kaki berulang-ulang", "Tidur", "Berdiri mematung"], answer: 1, solution: "1. Peregangan dinamis dilakukan sambil bergerak. 2. Contohnya mengayun lengan dan kaki. 3. Gerakan ini melenturkan otot sebelum berolahraga." },
{ q: "Memutar lengan saat pemanasan berguna untuk...", options: ["Melatih mata", "Melemaskan otot bahu dan lengan", "Menguatkan gigi", "Menambah tinggi badan"], answer: 1, solution: "1. Lengan dipakai di banyak cabang olahraga. 2. Putaran lengan melancarkan peredaran darah. 3. Otot bahu dan lengan menjadi lemas dan siap bergerak." },
{ q: "Urutan berolahraga yang benar adalah...", options: ["Pemanasan - inti - pendinginan", "Pendinginan - inti - pemanasan", "Inti saja", "Inti - pemanasan - pendinginan"], answer: 0, solution: "1. Olahraga diawali pemanasan agar otot siap. 2. Dilanjutkan gerakan inti sesuai cabang olahraga. 3. Diakhiri pendinginan agar tubuh kembali normal." },
{ q: "Pemanasan membuat otot menjadi...", options: ["Lemas tak bertenaga", "Keras seperti batu", "Kaku dan dingin", "Hangat dan lentur"], answer: 3, solution: "1. Otot yang dingin mudah cedera. 2. Gerakan pemanasan menaikkan suhu otot. 3. Otot yang hangat dan lentur siap dipakai berolahraga." },
{ q: "Contoh gerakan pendinginan adalah...", options: ["Lari sprint", "Berjalan pelan", "Push-up cepat", "Melompat tinggi"], answer: 1, solution: "1. Pendinginan dilakukan setelah olahraga inti. 2. Berjalan pelan menurunkan kerja jantung perlahan. 3. Tubuh kembali tenang secara bertahap." },
{ q: "Peregangan statis saat pendinginan dilakukan dengan...", options: ["Menahan posisi regangan beberapa detik", "Berlari cepat", "Berguling", "Melompat-lompat"], answer: 0, solution: "1. Peregangan statis dilakukan tanpa gerakan. 2. Posisi regangan ditahan beberapa detik. 3. Otot yang tegang setelah olahraga menjadi rileks." },
{ q: "Saat pendinginan, napas diatur dengan cara...", options: ["Bernapas cepat-cepat", "Tidak bernapas", "Menahan napas lama", "Menarik napas dalam secara perlahan"], answer: 3, solution: "1. Setelah olahraga napas masih cepat. 2. Tarik napas dalam lewat hidung secara perlahan. 3. Napas teratur membuat jantung kembali normal." },
{ q: "Pendinginan bertujuan...", options: ["Menambah berat badan", "Menambah kecepatan", "Mengembalikan detak jantung dan napas menjadi normal", "Membuat otot tegang"], answer: 2, solution: "1. Olahraga membuat jantung berdetak cepat. 2. Berhenti mendadak bisa membuat pusing. 3. Pendinginan menurunkan kerja tubuh perlahan hingga normal." },
{ q: "Pakaian olahraga yang baik adalah yang...", options: ["Ketat dan panas", "Menyerap keringat", "Terbuat dari plastik", "Berlapis-lapis tebal"], answer: 1, solution: "1. Olahraga membuat tubuh berkeringat. 2. Pakaian penyerap keringat membuat tubuh tetap kering. 3. Tubuh yang kering terasa nyaman saat bergerak." },
{ q: "Sebelum bermain, lapangan harus diperiksa dari...", options: ["Suara burung", "Benda tajam dan kerikil", "Warna cat", "Jumlah penonton"], answer: 1, solution: "1. Lapangan bisa menyimpan benda berbahaya. 2. Benda tajam dan kerikil bisa melukai kaki. 3. Lapangan yang bersih membuat bermain aman." },
{ q: "Saat sedang demam sebaiknya...", options: ["Berlari maraton", "Berenang", "Tetap berolahraga keras", "Istirahat dan tidak berolahraga"], answer: 3, solution: "1. Demam tanda tubuh sedang melawan penyakit. 2. Olahraga saat sakit membuat tubuh makin lemah. 3. Istirahat membantu tubuh cepat pulih." },
{ q: "Minum saat berolahraga sebaiknya...", options: ["Tidak minum sama sekali", "Secukupnya saat haus", "Minum sebanyak-banyaknya sekaligus", "Minum minuman bersoda"], answer: 1, solution: "1. Olahraga mengeluarkan banyak keringat. 2. Cairan tubuh perlu diganti dengan minum. 3. Minum secukupnya saat haus, jangan berlebihan agar perut nyaman." },
{ q: "Luka kecil karena jatuh sebaiknya...", options: ["Dibiarkan kotor", "Dibersihkan lalu diberi obat dan plester", "Ditutup tanah", "Dijilat"], answer: 1, solution: "1. Luka kecil bisa dimasuki kuman. 2. Bersihkan luka dengan air bersih. 3. Beri obat dan plester agar cepat sembuh." },
{ q: "Kaki yang keseleo sebaiknya...", options: ["Dikompres dingin dan diistirahatkan", "Dipijat keras-keras", "Direndam air panas", "Terus dipakai berlari"], answer: 0, solution: "1. Keseleo membuat sendi bengkak dan nyeri. 2. Kompres dingin mengurangi bengkak. 3. Istirahatkan kaki agar cepat pulih." },
{ q: "Saat mimisan, kepala sebaiknya...", options: ["Digeleng-gelengkan", "Dibiarkan menetes", "Ditengadahkan ke atas", "Ditundukkan sambil memencet hidung"], answer: 3, solution: "1. Mimisan adalah keluarnya darah dari hidung. 2. Tundukkan kepala agar darah tidak tertelan. 3. Pencet hidung perlahan untuk menghentikan darah." },
{ q: "Di tepi kolam renang dilarang berlari karena...", options: ["Airnya dingin", "Lantai licin bisa terpeleset", "Pengawas marah", "Teman iri"], answer: 1, solution: "1. Tepi kolam selalu basah. 2. Lantai basah sangat licin. 3. Berlari bisa terpeleset dan terbentur hingga jatuh ke kolam." },
{ q: "Saat bersepeda atau bermain sepatu roda, lutut dilindungi dengan...", options: ["Kacamata hitam", "Sarung tangan", "Pelindung lutut (deker)", "Topi"], answer: 2, solution: "1. Lutut mudah terbentur saat jatuh. 2. Pelindung lutut menahan benturan. 3. Memakainya membuat bermain lebih aman." },
{ q: "Posisi duduk yang baik adalah...", options: ["Bersandar miring", "Tiduran", "Punggung tegak", "Membungkuk"], answer: 2, solution: "1. Duduk lama dengan posisi salah membuat punggung sakit. 2. Punggung tegak menjaga tulang belakang lurus. 3. Duduk tegak juga membuat napas lega." },
{ q: "Tas sekolah sebaiknya...", options: ["Dibawa dengan gigi", "Diisi seberat mungkin", "Tidak terlalu berat", "Diseret di tanah"], answer: 2, solution: "1. Tas berat membebani punggung dan bahu. 2. Beban berlebih membuat punggung bungkuk. 3. Bawa hanya buku yang diperlukan hari itu." },
{ q: "Anak SD sebaiknya tidur cukup sekitar...", options: ["8 jam setiap malam", "15 jam sehari", "Tidak perlu tidur", "2 jam sehari"], answer: 0, solution: "1. Tidur membantu tubuh tumbuh dan pulih. 2. Anak SD butuh tidur sekitar 8 jam setiap malam. 3. Tidur cukup membuat besok segar dan fokus belajar." },
{ q: "Setelah belajar lama, tubuh dan mata perlu...", options: ["Begadang", "Istirahat sejenak", "Dipaksa terus", "Menatap layar lagi"], answer: 1, solution: "1. Belajar lama membuat mata lelah. 2. Tubuh yang duduk lama perlu digerakkan. 3. Istirahat sejenak membuat badan segar kembali." },
  ]
};
